  ".prev .ic{width:30px;height:30px;margin-bottom:8px}",
  ".dz{cursor:pointer}.dz:hover{border-color:var(--tx)}.dz img{max-width:100%;max-height:220px;border-radius:10px}",
  "input[type=range]{width:100%;accent-color:var(--tx);height:28px;cursor:pointer}",
  ".profile{display:flex;gap:14px;align-items:center}",
