  "/* ===== TEMA BIRU GELAP / PUTIH CERAH ===== */",
  ":root,:root[data-theme=dark]{color-scheme:dark;--bg:#0a1226;--sf:#101b36;--sf2:#15244a;--line:#22345c;--tx:#eaf1ff;--mut:#8fa3c8;--ac:#3b82f6;--onac:#fff;--ac2:#7db0ff;--gold:#f5b301;--sh:0 10px 28px rgba(0,0,0,.35)}",
  ":root[data-theme=light]{color-scheme:light;--bg:#f4f8ff;--sf:#fff;--sf2:#eef4ff;--line:#d6e2f7;--tx:#0b1b3a;--mut:#58698c;--ac:#1d5fe0;--onac:#fff;--ac2:#1d5fe0;--gold:#d99a00;--sh:0 10px 28px rgba(29,95,224,.14)}",
  ":root{--g1:#1d4ed8;--g2:#3b82f6}",
