  "",
  "/* ===== performa: ringan & halus ===== */",
  "html{-webkit-text-size-adjust:100%}",
  ".view.on{animation:vin .18s ease-out both}",
  "@keyframes vin{from{opacity:0;transform:translateY(6px)}}",
  ".card,.vban,.plan,.tb,.btn{backface-visibility:hidden}",
  "@media(hover:none){.card:hover,.big:hover{box-shadow:none;border-color:var(--line)}}",
  "/* ===== POLES TAMPILAN: kotak ringkas, tombol animatif ===== */",
  ":root{--ease:cubic-bezier(.2,.8,.2,1)}",
  ".cards{gap:9px}",
  ".card{min-height:0;justify-content:flex-start;gap:5px;padding:12px 6px 11px;border-radius:16px;position:relative;overflow:hidden;animation:cin .45s var(--ease) both}",
  ".card::before{content:\"\";position:absolute;inset:0;background:radial-gradient(120% 80% at 50% 0,rgba(59,130,246,.18),transparent 62%);opacity:0;transition:opacity .25s;pointer-events:none}",
  ".card>.ic:first-child{width:22px;height:22px;padding:8px;box-sizing:content-box;border-radius:13px;background:rgba(59,130,246,.14);transition:transform .28s var(--ease),background-color .2s}",
  ".card>.ic:last-child{display:none}",
  ".card b{margin-top:3px}",
  ".card:active{transform:scale(.96)}",
  "@media(hover:hover){.card:hover::before{opacity:1}.card:hover{transform:translateY(-3px)}.card:hover>.ic:first-child{transform:scale(1.08) rotate(-4deg);background:rgba(59,130,246,.26)}}",
  "@keyframes cin{from{opacity:0;transform:translateY(12px) scale(.97)}}",
  "@media(min-width:700px){.card{min-height:0;padding:16px 10px 14px}}",
  ".thead{margin-bottom:16px}",
  ".thead h2{font-size:23px}",
  ".cic{width:42px;height:42px;border-radius:13px;box-shadow:0 6px 16px rgba(37,99,235,.32);animation:pop .45s var(--ease) both}",
  ".panel{border-radius:16px;padding:16px;background:linear-gradient(180deg,var(--sf),var(--bg));box-shadow:0 6px 20px rgba(0,0,0,.14)}",
  ":root[data-theme=light] .panel{box-shadow:0 6px 18px rgba(29,95,224,.09)}",
  ".cols{gap:12px}",
  ".prev{min-height:150px;border-radius:14px;background:rgba(59,130,246,.04)}",
  ".prev>.ic,.prev .ic:first-child{animation:flt 2.8s ease-in-out infinite}",
  "@keyframes flt{50%{transform:translateY(-4px)}}",
  ".in,.sel{height:44px;border-radius:12px;transition:border-color .2s,box-shadow .25s}",
  ".in:focus,.sel:focus{box-shadow:0 0 0 3px rgba(59,130,246,.24)}",
  ".seg{border-radius:12px}",
  ".seg button{height:36px;border-radius:9px;transition:background-color .2s,color .2s,transform .15s,box-shadow .2s}",
  ".seg button:active{transform:scale(.96)}",
