  ".note{border-radius:12px}",
  ".btn{height:44px;border-radius:12px;font-size:14.5px;letter-spacing:.01em;box-shadow:0 6px 16px rgba(37,99,235,.28);transition:transform .15s var(--ease),box-shadow .2s,background-color .2s}",
  ".btn::after{content:\"\";position:absolute;top:0;bottom:0;left:-60%;width:40%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.32),transparent);transform:skewX(-20deg);transition:left .6s var(--ease);pointer-events:none}",
  "@media(hover:hover){.btn:hover{filter:none;transform:translateY(-1px);box-shadow:0 10px 22px rgba(37,99,235,.36)}.btn:hover::after{left:120%}}",
  ".btn:active{transform:scale(.97);box-shadow:0 3px 8px rgba(37,99,235,.3)}",
  ".btn.ghost{box-shadow:none}.btn.ghost::after{display:none}.btn.ghost:hover{background:var(--sf2);box-shadow:none}",
  ".btn[disabled]{opacity:1;cursor:wait;transform:none;background:linear-gradient(110deg,var(--g1) 30%,#60a5fa 50%,var(--g1) 70%);background-size:220% 100%;animation:bsh 1.3s linear infinite}",
  ".btn.ghost[disabled]{background:transparent;animation:none;opacity:.6}",
  "@keyframes bsh{to{background-position:-220% 0}}",
  ".cards .card:nth-child(2){animation-delay:0.06s}",
  ".cards .card:nth-child(3){animation-delay:0.09s}",
  ".cards .card:nth-child(4){animation-delay:0.12s}",
  ".cards .card:nth-child(5){animation-delay:0.15s}",
  ".cards .card:nth-child(6){animation-delay:0.18s}",
