  "/* ===== WARNA TOMBOL LEBIH LEMBUT + ANIMASI RINGAN (hanya transform/opacity) ===== */",
  ":root{--bt1:#2c55b4;--bt2:#3b6fd8;--ok:#34d399;--okbg:rgba(52,211,153,.1);--okln:rgba(52,211,153,.26)}",
  ":root[data-theme=light]{--bt1:#2a5fd0;--bt2:#3d7bea;--ok:#12a26e;--okbg:rgba(18,162,110,.09);--okln:rgba(18,162,110,.28)}",
  ".btn{height:42px;font-size:14px;font-weight:650;background:linear-gradient(180deg,var(--bt2),var(--bt1));box-shadow:0 1px 0 rgba(255,255,255,.16) inset,0 4px 12px rgba(30,64,140,.26);transition:transform .18s var(--ease),opacity .2s}",
  ".btn::after{left:0;width:45%;transform:translateX(-130%) skewX(-20deg);transition:transform .6s var(--ease);will-change:transform}",
  "@media(hover:hover){.btn:hover{transform:none;box-shadow:0 1px 0 rgba(255,255,255,.16) inset,0 6px 16px rgba(30,64,140,.32)}.btn:hover::after{left:0;transform:translateX(330%) skewX(-20deg)}}",
  ".btn:active{transform:scale(.98);box-shadow:0 1px 0 rgba(255,255,255,.16) inset,0 2px 6px rgba(30,64,140,.3)}",
  ".btn[disabled]{animation:none;opacity:.92;background:linear-gradient(180deg,var(--bt2),var(--bt1))}",
  ".btn[disabled]::after{transition:none;animation:bsw 1.3s ease-in-out infinite}",
  "@keyframes bsw{from{transform:translateX(-130%) skewX(-20deg)}to{transform:translateX(330%) skewX(-20deg)}}",
  ".btn.ghost,.btn.ghost[disabled]{background:transparent;box-shadow:none}",
  ".btn.ghost[disabled]{opacity:.6}",
  ".btn.dlb{height:42px;font-size:14px;background:linear-gradient(180deg,#3acb91,#1f9d6b);box-shadow:0 1px 0 rgba(255,255,255,.2) inset,0 4px 12px rgba(16,120,80,.28)}",
  ".seg{background:rgba(59,130,246,.07)}",
  ".seg button{transition:background-color .2s,color .2s,transform .15s}",
  ".seg button.on{background:rgba(59,130,246,.2);color:var(--ac2);box-shadow:inset 0 0 0 1px rgba(96,165,250,.45)}",
  ".tb.on{background:rgba(59,130,246,.2);color:var(--ac2);border-color:rgba(96,165,250,.45);box-shadow:none}",
  ".cic{background:linear-gradient(180deg,var(--bt2),var(--bt1));box-shadow:0 4px 12px rgba(30,64,140,.28)}",
  ".okb{padding:14px 16px;border-radius:14px;background:var(--okbg);border:1px solid var(--okln);gap:3px}",
  ".okk{background:rgba(52,211,153,.16)}",
  ".okk::after{border-color:var(--ok)}",
  ".okk svg{stroke:var(--ok)}",
