  "const $=s=>document.querySelector(s),grid=$('#grid');",
  "function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('on');clearTimeout(toast.x);toast.x=setTimeout(()=>t.classList.remove('on'),2200)}",
