  "let qRaf=0;$('#q').addEventListener('input',e=>{const el=e.target;cancelAnimationFrame(qRaf);qRaf=requestAnimationFrame(()=>{const v=el.value.trim().toLowerCase();render(T.filter(x=>(x.n+' '+x.d).toLowerCase().includes(v)),v)})});",
