  "const empty=(k,t)=>`<div class=\"prev\"><div>${ic(k)}<div>${t}</div></div></div>`;",
  "const V={",
  "dl:x=>`<div class=\"cols two\"><div class=\"panel\"><div class=\"f\"><label>Tautan</label><input class=\"in\" placeholder=\"${x.ph}\"></div><div class=\"f\"><label>Format</label>${seg(['MP4 Video','MP3 Audio'])}</div>${go}Proses</button></div><div class=\"panel\">${empty('dl','Hasil unduhan akan tampil di sini')}</div></div>`,",
  "yt:()=>`<div class=\"cols two\"><div class=\"panel\"><div class=\"f\"><label>Tautan YouTube</label><input class=\"in\" placeholder=\"Tempel tautan video\"></div><div class=\"row f\"><div><label>Mulai</label><input class=\"in\" id=\"ys\" value=\"00:30\" readonly></div><div><label>Selesai</label><input class=\"in\" id=\"ye\" value=\"01:15\" readonly></div></div><div class=\"f\"><label>Geser waktu mulai</label><input type=\"range\" id=\"rs\" min=\"0\" max=\"600\" value=\"30\" oninput=\"yu()\"></div><div class=\"f\"><label>Geser waktu selesai</label><input type=\"range\" id=\"re\" min=\"0\" max=\"600\" value=\"75\" oninput=\"yu()\"></div><p id=\"yd\" style=\"color:var(--ac2);font-size:13.5px;margin-bottom:16px\">Durasi klip: 45 detik</p><div class=\"f\"><label>Kualitas</label>${seg(['360p','720p','1080p'])}</div>${go}Buat klip</button></div><div class=\"panel\">${empty('yt','Pratinjau klip')}</div></div>`,",
  "st:x=>`<div class=\"cols two\"><div class=\"panel\"><div class=\"f\"><label>Nama pengguna</label><input class=\"in\" placeholder=\"${x.ph}\"></div>${go}Cari akun</button><div class=\"note\">${ic('eye')}<span>Hanya menampilkan data akun yang bersifat publik.</span></div></div><div class=\"panel\"><div class=\"profile\"><div class=\"av\"></div><div style=\"flex:1\"><div class=\"sk\" style=\"width:55%\"></div><div class=\"sk\" style=\"width:35%\"></div></div></div><div class=\"sk\" style=\"width:90%;margin-top:18px\"></div><div class=\"sk\" style=\"width:70%\"></div><div class=\"mini\"><div><b>-</b><br><small style=\"color:var(--mut)\">Pengikut</small></div><div><b>-</b><br><small style=\"color:var(--mut)\">Mengikuti</small></div><div><b>-</b><br><small style=\"color:var(--mut)\">Postingan</small></div></div></div></div>`,",
  "wmp:()=>gView('wmp'),",
