  "/* ---------- 4. Chat WA (720 x 1416) ---------- */",
  "function waIcon(c,k,cx,cy,col){const P={",
  "reply:['M9 17 4 12 9 7','M20 18v-2a4 4 0 0 0-4-4H4'],",
  "fwd:['m15 17 5-5-5-5','M4 18v-2a4 4 0 0 1 4-4h12'],",
  "copy:['M10 8h10a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H10a2 2 0 0 1-2-2V10a2 2 0 0 1 2-2z','M4 16a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2'],",
  "star:['M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z'],",
  "bin:['M3 6h18','M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6','M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2','M10 11v6','M14 11v6']}[k];",
  "c.save();c.translate(cx-20,cy-20);c.scale(40/24,40/24);c.strokeStyle=col;c.lineWidth=1.7;c.lineCap='round';c.lineJoin='round';P.forEach(d=>c.stroke(new Path2D(d)));c.restore()}",
  "async function waDraw(){const cv=$('#gcv');if(!cv)return;await gLoad(['600 31px Inter','400 30px Inter','900 40px Nunito']);",
  "const W=720,H=1416,c=gSetup(cv,W,H,1080);",
  "const fam='Inter,\"SF Pro Text\",-apple-system,\"Helvetica Neue\",Arial,sans-serif';",
  "/* latar buram gelap */",
  "c.fillStyle='#0b0b0c';c.fillRect(0,0,W,H);",
  "c.save();c.beginPath();c.rect(0,0,W,650);c.clip();",
  "const blobs=[[190,110,300,110,'rgba(135,135,135,.95)'],[300,250,330,80,'rgba(110,110,110,.85)'],[260,390,340,90,'rgba(100,100,100,.8)'],[320,530,300,90,'rgba(90,90,90,.8)'],[190,620,260,70,'rgba(120,108,85,.7)']];",
  "const t=document.createElement('canvas');t.width=144;t.height=130;const x=t.getContext('2d');x.scale(.2,.2);x.fillStyle='#0b0b0c';x.fillRect(0,0,W,650);blobs.forEach(([cx,cy,rx,ry,col])=>{const g=x.createRadialGradient(cx,cy,5,cx,cy,rx);g.addColorStop(0,col);g.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=g;x.save();x.translate(cx,cy);x.scale(1,ry/rx);x.translate(-cx,-cy);x.beginPath();x.arc(cx,cy,rx,0,7);x.fill();x.restore()});",
  "c.imageSmoothingEnabled=true;c.drawImage(t,0,0,W,650);c.restore();",
  "c.fillStyle='rgba(0,0,0,.92)';c.fillRect(580,0,140,700);",
  "let g=c.createLinearGradient(0,560,0,700);g.addColorStop(0,'rgba(11,11,12,0)');g.addColorStop(1,'rgba(11,11,12,1)');c.fillStyle=g;c.fillRect(0,560,W,140);",
  "/* bar reaksi */",
  "c.fillStyle='#262628';gRR(c,32,655,656,118,59);c.fill();",
  "c.textAlign='center';c.textBaseline='middle';c.font='54px \"Apple Color Emoji\",\"Segoe UI Emoji\",\"Noto Color Emoji\",sans-serif';",
  "['👍','❤️','😂','😮','😢','🙏'].forEach((e,i)=>c.fillText(e,92+i*76,718));",
