  "async function loadMe(){try{const r=await fetch('/me',{cache:'no-store'}),d=await r.json();if(!d.ok)return;const was=!!ME.vip;const oo=JSON.stringify(ME.off||[])+JSON.stringify(ME.names||{});ME={vip:d.vip,lim:d.lim,off:d.off||[],limits:d.limits||null,names:d.names||{},wa:d.wa||ME.wa||'',vlim:d.vlim||null,ch:d.ch||ME.ch||'',tr:d.trial!==false};applyNames();try{localStorage.setItem('alz_me',JSON.stringify(ME))}catch(e){}buildNav();paintQuota();if(was!==!!ME.vip||oo!==JSON.stringify(ME.off)+JSON.stringify(ME.names)){render(T,'');route()}}catch(e){}}",
