  "if(vStep===1){h+=`<div class=\"plans\">${pl.map(p=>`<button type=\"button\" class=\"plan ${vForm.p===p.id?'on':''}\" onclick=\"vForm.p='${p.id}';vGo(2)\"><b>${esc(p.name)}</b><span class=\"pr\">${rp(p.price)}</span><small>${p.days} hari${p.note?' · '+esc(p.note):''}</small></button>`).join('')}</div>`}",
