  "function vNew(){vStep=1;localStorage.removeItem('alz_order');OS=null;clearTimeout(poT);drawVip()}",
  "function shrinkImg(f,max){return new Promise((ok,no)=>{const u=URL.createObjectURL(f),i=new Image();i.onload=()=>{URL.revokeObjectURL(u);const k=Math.min(1,max/Math.max(i.naturalWidth,i.naturalHeight)),c=document.createElement('canvas');c.width=Math.round(i.naturalWidth*k);c.height=Math.round(i.naturalHeight*k);c.getContext('2d').drawImage(i,0,0,c.width,c.height);let q=.82,d=c.toDataURL('image/jpeg',q);while(d.length>1.5e6&&q>.4){q-=.1;d=c.toDataURL('image/jpeg',q)}ok(d)};i.onerror=()=>{URL.revokeObjectURL(u);no(new Error('Gambar tidak bisa dibaca'))};i.src=u})}",
